package com.geeksville.mesh.convoy

/*
 * STEP16C-2026-11-11: TEST-ONLY copy of 2.7e's ConvoyDownloadQueue.kt (DownloadQueueManager.enqueueArea, both overloads) -- the OLD side of the step 16c certification (GtCert16c).
 * GENERATED by make_old_copies_16c.py from the 2.7e source; do not edit by hand. Changes, and only these: no init / saveQueue / startNextIfAvailable / live queue -- the entries go to [collected], in the order 2.7e appends them.
 * ⚠ TEST-ONLY (CODE RULE 3): remove with GtCertRun before 2.8 is released.
 */

import android.content.Context
import java.io.File

object DownloadQueueCertOld {
    private const val TAG = "DownloadQueue"
    /** what enqueueArea appended (2.7e: _queue.value), in order -- the cert takes and clears it after each call */
    val collected = ArrayList<QueueEntry>()
    /** VectorTilesCertOld's recipe folder (2.7e: GroupTrackStorage.dir("recipes")) -- the cert sets it per case */
    var recipesDir: File = File("/nonexistent-cert16c")

    /** Unified area download: one slot, broken into grid cells */
    fun enqueueArea(
        context: Context,
        slotName: String,
        north: Double, south: Double, east: Double, west: Double,
        replaceExisting: Boolean = false
    ): Int = enqueueArea(context, slotName, north, south, east, west, replaceExisting, what = "")   // VECTRACKNAMES-2026-10-31: no label suffix

    /** VECTRACKNAMES-2026-10-31: [what] is added to each job's label ("DL VEC 1/2 \u00b7 Bar 10"); "" = none. CODE RULE 1: required here,
     *  the form above states "" for every caller that has nothing to add. */
    fun enqueueArea(
        context: Context,
        slotName: String,
        north: Double, south: Double, east: Double, west: Double,
        replaceExisting: Boolean,
        what: String
    ): Int {
        val sfx = if (what.isBlank()) "" else " \u00b7 $what"   // VECTRACKNAMES-2026-10-31
        // VECSOURCE-2026-10-30: VEC is not in getDownloadSources (not a map-bar slot) -- it is one layer.
        val slotLayers = if (slotName == VectorTiles.SLOT || slotName == ElevationTiles.SLOT) 1   // DEMSOURCE-2026-10-30: DEM is one layer too
            else MapSourceManager.getDownloadSources().filter { it.first == slotName }.sumOf { it.second.size }
        // SEGMENTATION (2026-07-11): size off REAL job volume = 1-layer estimate * slotLayers.
        //   SAT = 3 layers over same geography, so slotLayers=3 -> ~24.7K*3 = ~74K -> 2 segments.
        //   (Bug history: sizing off the bare 1-layer estimate under-segmented; caught by dry-run JSON.)
        // VECENQUEUE-2026-10-30: VEC is counted z0-z14 and sized on its OWN volume (a recipe box on the SAT z18 grid OOMed).
        val isVec = slotName == VectorTiles.SLOT || slotName == ElevationTiles.SLOT   // DEMSOURCE-2026-10-30: elevation rides the vector path
        val vecZ = if (slotName == ElevationTiles.SLOT) ElevationTiles.Z_MAX else VectorTiles.Z_MAX   // DEMSOURCE-2026-10-30: DEM z0-12, VEC z0-14
        val oneLayerTiles = if (isVec) ConvoyTileCalculator.quickEstimate(north, south, east, west, zMin = 0, zMax = vecZ).tileCount
            else ConvoyTileCalculator.quickEstimate(north, south, east, west).tileCount
        // ALL SOURCES RIDE THE SAT-SIZED GRID (design: "SAT sizes the grid, all ride it").
        // enqueueArea is called once per slot from submitDownload's loop; without this,
        // SAT (3 layers ~74K) split into 2 but TOPO/TOPO+ (~24K) stayed 1 -> mismatched grids.
        // So size off the SAT slot's layer count REGARDLESS of which slot is enqueuing:
        val satLayers = MapSourceManager.getDownloadSources()
            .find { it.first == "SAT" }?.second?.size ?: slotLayers
        val sizeTiles = if (isVec) oneLayerTiles else oneLayerTiles * Math.max(1, satLayers)
        val cells = ConvoyTileDownloader.segmentCells(north, south, east, west, sizeTiles)
        // SIZECALC-LOG-2026-07-23: every term of the sizing decision on one line.
        run {
            val entryTilesWhole =   // VECENQUEUE-2026-10-30: VEC never lists the box
                (if (isVec) oneLayerTiles else ConvoyTileCalculator.calculateTiles(north, south, east, west).size) * slotLayers
            android.util.Log.i(
                "SIZECALC",
                "src=enqueueArea label='DL $slotName' slot=$slotName " +
                "N=$north S=$south E=$east W=$west " +
                "dLat=${north - south} dLon=${east - west} " +
                "oneLayer=$oneLayerTiles slotLayers=$slotLayers satLayers=$satLayers " +
                "sizeTiles=$sizeTiles segments=${cells.size} " +
                "entryTilesWholeBox=$entryTilesWhole " +
                "perCellApprox=${entryTilesWhole / Math.max(1, cells.size)} " +
                "replace=$replaceExisting"
            )
        }
        if (cells.isEmpty()) {
            // Small area — single job
            val entry = QueueEntry(
                north = north, south = south, east = east, west = west,
                totalTiles = (if (isVec) oneLayerTiles else ConvoyTileCalculator.calculateTiles(north, south, east, west).size) * slotLayers,
                label = "DL $slotName" + sfx,   // VECTRACKNAMES-2026-10-31
                refreshMode = replaceExisting,
                refreshSlot = slotName,
                // QUEUE-SCHEMA-2026-07-24: this branch is UNREACHABLE - segmentCells
                // floors at Math.max(1,..) so cells is never empty. Typed
                // anyway so it cannot become a silent AREA-default if the
                // floor ever changes.
                downloadType = if (isVec) DownloadType.MAP_SOURCE_REFRESH else DownloadType.AREA,   // VECRFSH-2026-10-30: a recipe rebuild
                priority = if (isVec) DownloadPriority.REFRESH else DownloadPriority.AREA
            )
            val current = collected
            current.add(entry)
            return 1
        }
        val current = collected
        cells.forEachIndexed { i, cell ->
            val entry = QueueEntry(
                north = cell[0], south = cell[1], east = cell[2], west = cell[3],
                totalTiles = (if (isVec) ConvoyTileCalculator.quickEstimate(cell[0], cell[1], cell[2], cell[3], zMin = 0, zMax = vecZ).tileCount   // VECENQUEUE-2026-10-30
                    else ConvoyTileCalculator.calculateTiles(cell[0], cell[1], cell[2], cell[3]).size) * slotLayers,
                label = "DL $slotName ${i + 1}/${cells.size}" + sfx,   // VECTRACKNAMES-2026-10-31
                refreshMode = replaceExisting,
                refreshSlot = slotName,
                // QUEUE-SCHEMA-2026-07-24
                downloadType = if (isVec) DownloadType.MAP_SOURCE_REFRESH else DownloadType.AREA,   // VECRFSH-2026-10-30: a recipe rebuild
                priority = if (isVec) DownloadPriority.REFRESH else DownloadPriority.AREA
            )
            // SIZECALC-LOG-2026-07-23: per-cell entry as queued.
            android.util.Log.i(
                "SIZECALC",
                "  cell ${i + 1}/${cells.size} src=enqueueArea slot=$slotName " +
                "label='${entry.label}' entryTiles=${entry.totalTiles} " +
                "N=${cell[0]} S=${cell[1]} E=${cell[2]} W=${cell[3]} " +
                "id=${entry.id}"
            )
            current.add(entry)
        }
        android.util.Log.i(TAG, "Enqueued area: $slotName ${cells.size} cells replace=$replaceExisting")
        return cells.size
    }
}
